 $$('[data-row]',root).forEach(tr=>{const r=byKey.get(tr.dataset.row),d=drafts.get(tr.dataset.row);refreshPackaging(tr,d||{body:bodyFor(r),row:r},true);$('[data-category]',tr).textContent=categoryText((d?.row||r).category)||'—';if(d){d.element=tr;paintSaveState(tr,d)}else if(r.sheet_revision)$('[data-save-state]',tr).textContent='✓ Saved'});draftCount();
