function draftCount(){const count=pendingCount();$('[data-rp-drafts]').textContent=count?count+' row'+(count===1?'':'s')+' with unsaved changes · Autosave enabled':'All changes saved · Internal pricing sheet only';const ordered=filteredRows(),total=ordered.length,pages=pricingPages(ordered);$('[data-rp-results]').textContent=total+' results';const pager=$('[data-rp-pagination]');if(pager){pager.hidden=pages.length<=1;$('[data-rp-page-label]').textContent='Page '+(sheetPage+1)+' of '+pages.length+' · Product sizes kept together';$('[data-rp-prev]').disabled=sheetPage===0;$('[data-rp-next]').disabled=sheetPage>=pages.length-1}}
