 const filters=$('[data-rp-filters]'),applyFilters=()=>{clearTimeout(searchTimer);sheetPage=0;renderPricing()};filters.addEventListener('submit',e=>e.preventDefault());filters.addEventListener('input',e=>{if(e.target.name!=='q')return;clearTimeout(searchTimer);searchTimer=setTimeout(applyFilters,250)});filters.addEventListener('change',e=>{if(e.target.matches('select'))applyFilters()});filters.addEventListener('reset',()=>{clearTimeout(searchTimer);setTimeout(()=>{$$('select',filters).forEach(select=>select.dispatchEvent(new Event('change')));applyFilters()})});
